1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.service.ClinicService;
15	import org.springframework.samples.petclinic.util.HashUtils;
16	import org.springframework.samples.petclinic.util.IdentityUtils;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	import java.time.Period;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.OptionalInt;
25	
26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public abstract class OwnerMapper {
31	
32	    /** Used to count the members of an owner's household when deriving derived fields. */
33	    @Autowired
34	    protected ClinicService clinicService;
35	
36	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
37	    @Autowired
38	    protected CityRegionResolver cityRegionResolver;
39	
40	    /** Formats the stored E.164 telephone into its human-readable display form. */
41	    @Autowired
42	    protected TelephoneNormalizer telephoneNormalizer;
43	
44	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
45	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
46	    @Mapping(target = "displayName",
47	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "initials", expression = "java(initials(owner))")
49	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
50	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
51	    @Mapping(target = "locality", expression = "java(locality(owner))")
52	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
53	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
54	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
55	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
56	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
57	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
58	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
59	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
60	    public abstract OwnerDto toOwnerDto(Owner owner);
61	
62	    /**
63	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
64	     * owner has no id assigned yet.
65	     */
66	    String selfLink(Owner owner) {
67	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
68	    }
69	
70	    /**
71	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
72	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
73	     * fiscal year ending the following calendar year, while January–June belongs to the one
74	     * ending that same calendar year.
75	     */
76	    public static int fiscalYear(LocalDate date) {
77	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
78	    }
79	
80	    /**
81	     * The owner's fiscal year formatted 'FY<YY>', where YY is the last two digits of the
82	     * fiscal year of the (business-day-adjusted) {@code registrationDate} and the fiscal year
83	     * starts on 1 July. Returns null when no registrationDate has been assigned.
84	     */
85	    String fiscalYear(Owner owner) {
86	        LocalDate registrationDate = owner.getRegistrationDate();
87	        if (registrationDate == null) {
88	            return null;
89	        }
90	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
91	    }
92	
93	    /**
94	     * The owner's age band derived from {@code birthDate} relative to the
95	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
96	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
97	     * absent so no band can be computed.
98	     */
99	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
100	        LocalDate birthDate = owner.getBirthDate();
101	        LocalDate registrationDate = owner.getRegistrationDate();
102	        if (birthDate == null || registrationDate == null) {
103	            return null;
104	        }
105	        int age = Period.between(birthDate, registrationDate).getYears();
106	        if (age < 18) {
107	            return OwnerDto.AgeBandEnum.MINOR;
108	        }
109	        if (age < 65) {
110	            return OwnerDto.AgeBandEnum.ADULT;
111	        }
112	        return OwnerDto.AgeBandEnum.SENIOR;
113	    }
114	
115	    /**
116	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
117	     * contained in the customerCode, or null when no customerCode has been assigned.
118	     */
119	    Integer checkDigit(Owner owner) {
120	        String customerCode = owner.getCustomerCode();
121	        return customerCode == null ? null : luhn(customerCode);
122	    }
123	
124	    /**
125	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
126	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
127	     * reduced by 9, and the check digit makes the total a multiple of ten.
128	     */
129	    static int luhn(String s) {
130	        int sum = 0;
131	        boolean doubling = true;
132	        for (int i = s.length() - 1; i >= 0; i--) {
133	            char c = s.charAt(i);
134	            if (c < '0' || c > '9') {
135	                continue;
136	            }
137	            int d = c - '0';
138	            if (doubling) {
139	                d *= 2;
140	                if (d > 9) {
141	                    d -= 9;
142	                }
143	            }
144	            sum += d;
145	            doubling = !doubling;
146	        }
147	        return (10 - (sum % 10)) % 10;
148	    }
149	
150	    /**
151	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
152	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
153	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
154	     * detection on create — two owners are duplicates only when their whole identityKey matches,
155	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
156	     * different telephones derive different keys and are all permitted.
157	     */
158	    public static String identityKey(Owner owner) {
159	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
160	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
161	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
162	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
163	    }
164	
165	    /**
166	     * The owner's preferred contact channel: 'EMAIL' when an email address is
167	     * present, otherwise 'PHONE'.
168	     */
169	    String contactPreference(Owner owner) {
170	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
171	        return hasEmail ? "EMAIL" : "PHONE";
172	    }
173	
174	    /**
175	     * The owner's locality: the REGION component of the customerCode identity (the part before
176	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
177	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
178	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
179	     */
180	    String locality(Owner owner) {
181	        String customerCode = owner.getCustomerCode();
182	        if (customerCode != null) {
183	            int dash = customerCode.indexOf('-');
184	            if (dash >= 0) {
185	                return customerCode.substring(0, dash);
186	            }
187	        }
188	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
189	    }
190	
191	    /**
192	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
193	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
194	     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
195	     * otherwise 'REGIONAL'.
196	     */
197	    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
198	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
199	        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
200	        String area = knownRegion ? "METRO" : "REGIONAL";
201	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
202	    }
203	
204	    /**
205	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
206	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
207	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
208	     */
209	    String timezone(Owner owner) {
210	        return cityRegionResolver.timezoneForRegion(locality(owner));
211	    }
212	
213	    /**
214	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
215	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
216	     * the owner's tenure is more than one fiscal year.
217	     */
218	    public int membershipPoints(Owner owner) {
219	        int points = 0;
220	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
221	        if (hasEmail) {
222	            points += 2;
223	        }
224	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
225	        if (uniqueName) {
226	            points += 1;
227	        }
228	        if (householdSize(owner) >= 3) {
229	            points += 2;
230	        }
231	        LocalDate registrationDate = owner.getRegistrationDate();
232	        boolean tenured = registrationDate != null
233	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
234	        if (tenured) {
235	            points += 3;
236	        }
237	        return points;
238	    }
239	
240	    /**
241	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
242	     * via {@link #levelForPoints} and then held to the household level-ceiling by
243	     * {@link #cappedByHousehold}.
244	     */
245	    public int membershipLevel(Owner owner) {
246	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
247	    }
248	
249	    /**
250	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
251	     * one above the current maximum membershipLevel among the household members that already
252	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
253	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
254	     * household member exists no ceiling applies and {@code level} is returned unchanged.
255	     *
256	     * @param owner the owner whose own level is being capped
257	     * @param level the owner's uncapped membership level
258	     * @return the level, capped at one above the earlier household members' maximum
259	     */
260	    private int cappedByHousehold(Owner owner, int level) {
261	        Integer id = owner.getId();
262	        String householdId = owner.getHouseholdId();
263	        if (id == null || householdId == null) {
264	            return level;
265	        }
266	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
267	            .filter(existing -> !existing.isDeleted())
268	            .filter(existing -> existing.getId() != null && existing.getId() < id)
269	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
270	            .mapToInt(this::membershipLevel)
271	            .max();
272	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
273	    }
274	
275	    /**
276	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
277	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
278	     */
279	    int levelForPoints(int points) {
280	        if (points >= 6) {
281	            return 4;
282	        }
283	        if (points >= 4) {
284	            return 3;
285	        }
286	        if (points >= 2) {
287	            return 2;
288	        }
289	        return 1;
290	    }
291	
292	    /**
293	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
294	     * (including the owner itself once persisted). Returns an empty list when the owner has no
295	     * household id assigned.
296	     */
297	    List<Owner> householdMembers(Owner owner) {
298	        String householdId = owner.getHouseholdId();
299	        if (householdId == null) {
300	            return List.of();
301	        }
302	        return clinicService.findAllOwners().stream()
303	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
304	            .toList();
305	    }
306	
307	    /**
308	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
309	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
310	     * household id assigned.
311	     */
312	    int householdSize(Owner owner) {
313	        return householdMembers(owner).size();
314	    }
315	
316	    /**
317	     * The owner's salutation: the {@code title} and last name separated by a single space
318	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
319	     */
320	    String salutation(Owner owner) {
321	        String title = owner.getTitle();
322	        if (title == null || title.isBlank()) {
323	            return owner.getLastName();
324	        }
325	        return title + " " + owner.getLastName();
326	    }
327	
328	    /**
329	     * The upper-cased first letters of firstName and lastName, dot-separated with a
330	     * trailing dot, e.g. 'J.S.'.
331	     */
332	    String initials(Owner owner) {
333	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
334	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
335	    }
336	
337	    public abstract Owner toOwner(OwnerDto ownerDto);
338	
339	    @Mapping(target = "id", ignore = true)
340	    @Mapping(target = "pets", ignore = true)
341	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
342	
343	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
344	
345	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
346	
347	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
348	        OwnerPageDto ownerPageDto = new OwnerPageDto();
349	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
350	        ownerPageDto.setPage(ownerPage.getNumber());
351	        ownerPageDto.setSize(ownerPage.getSize());
352	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
353	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
354	        return ownerPageDto;
355	    }
356	}
