17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.service.ClinicService;
32	import org.springframework.samples.petclinic.util.HashUtils;
33	import org.springframework.samples.petclinic.util.IdentityUtils;
34	import org.springframework.stereotype.Component;
35	import org.springframework.web.util.UriComponentsBuilder;
36	
37	/**
38	 * Owns the owner-creation concern: the single place that turns a submitted
39	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
40	 * and reports the create outcome as the HTTP response the endpoint returns.
41	 *
42	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
43	 * registration-date and business-day handling, the per-day and per-city quotas, the
44	 * address/telephone/email/postcode normalization and validation, the household, duplicate
45	 * and soft-match identity rules, and the derived customer code, namesake count and
46	 * membership number — reads the one owner this class builds, in the one order it applies
47	 * them, so they can never drift apart. The controller is left holding only the endpoint's
48	 * HTTP boundary.
49	 */
50	@Component
51	public class OwnerRegistrar {
52	
53	    /** Minimal syntactic check for an email address: a non-empty local part, a single
54	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
55	    private static final Pattern EMAIL_PATTERN =
56	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
57	
58	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
59	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
60	
61	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
62	     *  these (case-insensitively) is refused with 400. */
63	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
64	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    private final AddressNormalizer addressNormalizer;
73	
74	    private final CityRegionResolver cityRegionResolver;
75	
76	    private final HouseholdResolver householdResolver;
77	
78	    private final OwnerAuditor ownerAuditor;
79	
80	    /**
81	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
82	     * produced, so a later create carrying the same key returns that same owner instead of
83	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
84	     * request; entries are keyed by the client-supplied key, which is expected to be unique
85	     * per logical create.
86	     */
87	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
88	        new java.util.concurrent.ConcurrentHashMap<>();
89	
90	    public OwnerRegistrar(ClinicService clinicService,
91	                          OwnerMapper ownerMapper,
92	                          TelephoneNormalizer telephoneNormalizer,
93	                          AddressNormalizer addressNormalizer,
94	                          CityRegionResolver cityRegionResolver,
95	                          HouseholdResolver householdResolver,
96	                          OwnerAuditor ownerAuditor) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.cityRegionResolver = cityRegionResolver;
102	        this.householdResolver = householdResolver;
103	        this.ownerAuditor = ownerAuditor;
104	    }
105	
106	    /**
107	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
108	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
109	     * (with a {@code Location} header and the created owner) on success, or the appropriate
110	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
111	     * the request. No owner is persisted unless every rule passes.
112	     *
113	     * @param ownerFieldsDto the submitted owner fields
114	     * @return the create outcome as an HTTP response
115	     */
116	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
117	        return register(ownerFieldsDto, null);
118	    }
119	
120	    /**
121	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
122	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
123	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
124	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
125	     * against the created owner so a later repeat resolves to the same owner.
126	     *
127	     * @param ownerFieldsDto the submitted owner fields
128	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
129	     * @return the create outcome as an HTTP response
130	     */
131	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
132	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
133	        if (key != null) {
134	            Integer existingId = idempotencyKeys.get(key);
135	            if (existingId != null) {
136	                Owner original = this.clinicService.findOwnerById(existingId);
137	                if (original != null) {
138	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
139	                }
140	                // The originally created owner is gone; forget the stale key and create afresh.
141	                idempotencyKeys.remove(key);
142	            }
143	        }
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        if (owner.getRegistrationDate() == null) {
147	            owner.setRegistrationDate(LocalDate.now());
148	        }
149	        // A supplied registration date may not be later than the server's current date.
150	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
151	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	        }
153	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
154	        LocalDate registrationDate = owner.getRegistrationDate();
155	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
156	            .map(Owner::getRegistrationDate)
157	            .filter(registrationDate::equals)
158	            .count();
159	        if (ownersCreatedThatDay >= 100) {
160	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
161	        }
162	        String address = normalizedAddress(owner);
163	        if (address == null) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        owner.setAddress(address);
167	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
168	        if (telephone == null) {
169	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
170	        }
171	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setTelephone(telephone);
175	        String email = owner.getEmail();
176	        if (email != null) {
177	            email = email.trim();
178	            if (!EMAIL_PATTERN.matcher(email).matches()) {
179	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
180	            }
181	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
182	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	            owner.setEmail(email.toLowerCase(Locale.ROOT));
186	        }
187	        // A postcode is optional, but when supplied it must be four digits and valid for the
188	        // owner's city per the fixed region table; a city with no known region accepts any
189	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
190	        String postcode = owner.getPostcode();
191	        if (postcode != null) {
192	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
193	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
194	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
195	            }
196	        }
197	        // The owner's telephone and email are now in their canonical, stored form.
198	        // The household id is deterministic: owners with the same normalized last name and
199	        // postcode share it automatically. Assign it unconditionally so the membership-level
200	        // ceiling can key off it; it no longer participates in duplicate detection, which now
201	        // rests solely on the identity key below.
202	        owner.setHouseholdId(householdResolver.householdId(owner));
203	        // Duplicate detection is the single identity key: a candidate is rejected only when its
204	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
205	        // collides with a non-deleted owner's. Two people sharing a household with different
206	        // telephones therefore derive different keys and are both admitted; the second is instead
207	        // flagged as a possible duplicate by the soft-match rule below.
208	        if (isDuplicateOwner(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
212	        long ownersInCity = this.clinicService.findAllOwners().stream()
213	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
214	            .count();
215	        if (ownersInCity >= 50) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
219	        // rejected above). ownersInCity counts the existing owners the candidate is joining.
220	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
221	        owner.setCustomerCode(customerCode(owner));
222	        owner.setNamesakeCount(namesakeCount(owner));
223	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
224	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
225	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
226	        // identityKey may still differ from an existing owner's while their last names sound alike
227	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
228	        // under a different telephone or email. When it does, it is created but flagged as a
229	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
230	        // is recorded.
231	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
232	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
233	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
234	        this.clinicService.saveOwner(owner);
235	        if (key != null) {
236	            idempotencyKeys.put(key, owner.getId());
237	        }
238	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
239	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    /**
246	     * The owner's postal address in the single canonical form under which it is stored, or
247	     * {@code null} when the owner supplies no usable address. An owner may supply its address
248	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
249	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
250	     *
251	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
252	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
253	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
254	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
255	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
256	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
257	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
258	     * the caller can reject the request with 400.
259	     *
260	     * <p>This is the single point at which an owner's address is resolved and normalized on
261	     * create, so every rule keyed on the stored address reads the one value produced here.
262	     *
263	     * @param owner the owner about to be created
264	     * @return the canonical stored address, or {@code null} when the owner supplies none
265	     */
266	    private String normalizedAddress(Owner owner) {
267	        String rawLine1 = owner.getAddressLine1();
268	        if (rawLine1 != null && !rawLine1.isBlank()) {
269	            String line1 = addressNormalizer.normalize(rawLine1);
270	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
271	            owner.setAddressLine1(line1);
272	            owner.setAddressLine2(line2.isBlank() ? null : line2);
273	            return line2.isBlank() ? line1 : line1 + " " + line2;
274	        }
275	        owner.setAddressLine1(null);
276	        owner.setAddressLine2(null);
277	        String address = addressNormalizer.normalize(owner.getAddress());
278	        return address.isBlank() ? null : address;
279	    }
280	
281	    /**
282	     * Whether {@code candidate} collides with an already-registered owner under the single
283	     * identity rule enforced on create. This is the one point at which a new owner is
284	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
285	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
286	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
287	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
288	     * existing owner's; because the telephone is part of the key, two people sharing a household
289	     * (a like-sounding last name and postcode) with different telephones have different
290	     * identityKeys and are both allowed.
291	     *
292	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
293	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
294	     * genuinely the same identity.
295	     *
296	     * @param candidate the fully-normalized owner about to be created
297	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
298	     */
299	    private boolean isDuplicateOwner(Owner candidate) {
300	        String identityKey = OwnerMapper.identityKey(candidate);
301	        return this.clinicService.findAllOwners().stream()
302	            .filter(existing -> !existing.isDeleted())
303	            .map(OwnerMapper::identityKey)
304	            .anyMatch(identityKey::equals);
305	    }
306	
307	    /**
308	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
309	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
310	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
311	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
312	     * of the same person under a different telephone or email. Both must supply a postcode for a
313	     * match to be possible; when several existing owners qualify the lowest id is returned so the
314	     * result is deterministic.
315	     *
316	     * @param candidate the fully-normalized owner about to be created
317	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
318	     */
319	    private Integer possibleDuplicateOf(Owner candidate) {
320	        String postcode = candidate.getPostcode();
321	        if (postcode == null || postcode.isBlank()) {
322	            return null;
323	        }
324	        String identityKey = OwnerMapper.identityKey(candidate);
325	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> !existing.isDeleted()
328	                && !identityKey.equals(OwnerMapper.identityKey(existing))
329	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
330	                && postcode.equals(existing.getPostcode()))
331	            .map(Owner::getId)
332	            .filter(java.util.Objects::nonNull)
333	            .min(Integer::compareTo)
334	            .orElse(null);
335	    }
336	
337	    /**
338	     * Build the customer code assigned to {@code owner} on create, formatted
339	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
340	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
341	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
342	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
343	     *
344	     * <p>When the computed code collides with an already-registered owner's customerCode it is
345	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
346	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
347	     */
348	    private String customerCode(Owner owner) {
349	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
350	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
351	        String base = region + "-" + hash8;
352	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
353	            .map(Owner::getCustomerCode)
354	            .filter(java.util.Objects::nonNull)
355	            .collect(java.util.stream.Collectors.toSet());
356	        if (!existing.contains(base)) {
357	            return base;
358	        }
359	        int n = 2;
360	        while (existing.contains(base + "-" + n)) {
361	            n++;
362	        }
363	        return base + "-" + n;
364	    }
365	
366	    /**
367	     * The number of existing owners that share {@code owner}'s firstName and lastName,
368	     * compared case-insensitively. The candidate is not yet stored at the point this is
369	     * assigned, so it does not count itself. This is the value stored as the owner's
370	     * namesakeCount on create.
371	     */
372	    private int namesakeCount(Owner owner) {
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
375	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
376	            .count();
377	    }
378	
379	    /** Fixed list of public holidays that a registration date must roll past. */
380	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
381	        LocalDate.of(2026, 1, 1),
382	        LocalDate.of(2026, 1, 26),
383	        LocalDate.of(2026, 4, 25),
384	        LocalDate.of(2026, 12, 25),
385	        LocalDate.of(2026, 12, 28));
386	
387	    /**
388	     * Roll a registration date forward to the next business day: a Saturday, Sunday
389	     * or listed public holiday advances one day at a time until it lands on a weekday
390	     * that is not a public holiday. A plain weekday is returned unchanged.
391	     */
392	    private static LocalDate toBusinessDay(LocalDate date) {
393	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
394	            date = date.plusDays(1);
395	        }
396	        return date;
397	    }
398	
399	    private static boolean isWeekend(LocalDate date) {
400	        return switch (date.getDayOfWeek()) {
401	            case SATURDAY, SUNDAY -> true;
402	            default -> false;
403	        };
404	    }
405	
406	    /**
407	     * Build the membership number assigned on create, formatted
408	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
409	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
410	     * 'NSW-1A2B3C4D-M26'.
411	     */
412	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
413	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
414	        return customerCode + "-M" + yy;
415	    }
